import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        records = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns and columns[0].startswith("\ufeff"):
        columns[0] = columns[0][1:]

    rows = records[1:]
    width = max([11, len(columns)] + [len(row) for row in rows])
    used_names = set(columns)

    while len(columns) < width:
        number = len(columns) + 1
        name = "column_{}".format(number)
        while name in used_names:
            number += 1
            name = "column_{}".format(number)
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
